// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, uint256 e) public {
        amount = bound(amount, 1 ether, 100 ether);
        e = bound(e, 1 ether, 100 ether);

        Attacker a = new Attacker(c);
        vm.deal(address(a), amount + e);

        // deposit `amount`, then withdrawAll; during the payout the attacker
        // re-enters exactly once with a fresh deposit of `e`.
        a.attack(amount, e);

        // In the reference, credit is cleared AFTER the external call, so the
        // re-entrant deposit of `e` is wiped: c keeps that ether and a later
        // withdrawAll pays nothing.
        // In the mutant, credit was cleared BEFORE the call, so the re-entrant
        // deposit of `e` survives and a later withdrawAll pays it out, draining c.
        a.go();

        assertTrue(address(c).balance == e);
    }
}

contract Attacker {
    ReentrancyDAO c;
    bool private entered;
    uint256 private e;

    constructor(ReentrancyDAO c_) { c = c_; }

    function attack(uint256 amount, uint256 e_) external {
        e = e_;
        c.deposit{value: amount}();
        c.withdrawAll();
    }

    function go() external {
        c.withdrawAll();
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            c.deposit{value: e}();
        }
    }
}
